Item.method_code:
const additionalData = target.additional_data || {};
const permissionId = additionalData.permissionId;

const item = window.getItem();
aras.setItemProperty(item, 'permission_id', permissionId);
item.selectSingleNode('permission_id').removeAttribute('keyed_name');
if (!item.getAttribute('action')) {
	item.setAttribute('action', 'update');
}

options.notifyObserver('UpdateTearOffWindowState');
